$db->query("UPDATE lessons SET content_en=short_notes_en WHERE short_notes_en IS NOT NULL AND short_notes_en<>'' AND ((content_en IS NULL OR content_en='') OR short_description_en LIKE 'Admin-imported notes%' OR short_description_en LIKE 'Imported % textbook%')");
$db->query("UPDATE lessons SET content_si=short_notes_si WHERE short_notes_si IS NOT NULL AND short_notes_si<>'' AND ((content_si IS NULL OR content_si='') OR short_description_si LIKE 'Admin-imported notes%' OR short_description_si LIKE 'Imported % textbook%')");
$db->query("UPDATE lessons SET content_ta=short_notes_ta WHERE short_notes_ta IS NOT NULL AND short_notes_ta<>'' AND ((content_ta IS NULL OR content_ta='') OR short_description_ta LIKE 'Admin-imported notes%' OR short_description_ta LIKE 'Imported % textbook%')");
