function studio_python():string{if(PHP_OS_FAMILY!=='Windows')return 'python3';$configured=(string)getenv('CURRICULUM_PYTHON');if($configured!==''&&is_file($configured))return $configured;$base=(string)getenv('LOCALAPPDATA');$matches=$base!==''?glob($base.'/Programs/Python/Python*/python.exe'):[];if($matches){sort($matches,SORT_NATURAL);return (string)end($matches);}return 'python';}
function studio_validate_text(string $text):string{$sample=mb_substr($text,0,12000);$medium=(string)($_POST['medium']??'');$si=preg_match_all('/[\x{0D80}-\x{0DFF}]/u',$sample);$ta=preg_match_all('/[\x{0B80}-\x{0BFF}]/u',$sample);if($medium==='English'&&($si>50||$ta>50))throw new RuntimeException('This PDF is not English medium. It contains '.($si>$ta?'Sinhala':'Tamil').' textbook text. Choose the matching medium or upload the English book.');if($medium==='Sinhala'&&$ta>50)throw new RuntimeException('This PDF appears to be Tamil medium, not Sinhala.');if($medium==='Tamil'&&$si>50)throw new RuntimeException('This PDF appears to be Sinhala medium, not Tamil.');$selected=(int)(query_one('SELECT grade_number FROM grades WHERE id=?','i',[(int)($_POST['grade_id']??0)])['grade_number']??0);$detected=0;if(preg_match('/\bgrade\s*[-–:]?\s*0?(\d{1,2})\b/i',$sample,$m)||preg_match('/0?(\d{1,2})\s*ශ්‍රේණි/u',$sample,$m)||preg_match('/தரம்\s*[-–:]?\s*0?(\d{1,2})/u',$sample,$m))$detected=(int)$m[1];if($selected&&$detected&&$selected!==$detected)throw new RuntimeException("This PDF is Grade $detected, but Grade $selected was selected. Upload the correct textbook or change the grade.");return $text;}
function studio_seed_sections(array $sections,array $pages):void{
    if(($_POST['kind']??'notes')!=='notes'||count($sections)<2)return;
    $grade=(int)($_POST['grade_id']??0);$subject=(int)($_POST['subject_id']??0);$medium=(string)($_POST['medium']??'');
    $field=['Sinhala'=>'si','Tamil'=>'ta','English'=>'en'][$medium]??null;if(!$grade||!$subject||!$field)return;
    $firstPage=(int)($sections[0]['pdf_page']??1);
    $bookText=trim(implode("\n\n",array_column(array_values(array_filter($pages,fn($page)=>(int)$page['page']>=$firstPage)),'text')));
    $textStarts=[];$cursor=0;
    foreach($sections as $section){$searchTitle=trim((string)(preg_split('/\s+-\s+/',(string)$section['title'],2)[0]??$section['title']));$position=stripos($bookText,$searchTitle,$cursor);$textStarts[]=$position===false?null:$position;if($position!==false)$cursor=$position+strlen($searchTitle);}
    $db=db();$db->begin_transaction();
    try{
        $parts=[];
        foreach($sections as $index=>$section){
            $number=(int)$section['number'];$start=(int)$section['pdf_page'];$end=(int)($sections[$index+1]['pdf_page']??PHP_INT_MAX);
            $content=trim(implode("\n\n",array_column(array_values(array_filter($pages,fn($page)=>(int)$page['page']>=$start&&(int)$page['page']<$end)),'text')));
            if(mb_strlen($content)<100&&$textStarts[$index]!==null){$finish=$textStarts[$index+1]??strlen($bookText);$content=trim(substr($bookText,$textStarts[$index],$finish-$textStarts[$index]));}
            if(mb_strlen($content)<100)continue;
            $title=trim((string)$section['title']);$unit=query_one('SELECT id FROM units WHERE grade_id=? AND subject_id=? AND unit_number=?','iii',[$grade,$subject,$number]);
            if($unit)$unitId=(int)$unit['id'];else{$u=$db->prepare('INSERT INTO units(grade_id,subject_id,unit_number,name_en,name_si,name_ta,display_order,status) VALUES(?,?,?,?,?,?,?,"active")');$u->bind_param('iiisssi',$grade,$subject,$number,$title,$title,$title,$number);$u->execute();$unitId=(int)$db->insert_id;}
            $lesson=query_one("SELECT id FROM lessons WHERE grade_id=? AND subject_id=? AND medium=? AND display_order=? ORDER BY id LIMIT 1",'iisi',[$grade,$subject,$medium,$number]);
            $summary=implode("\n",array_slice(array_values(array_filter(array_map('trim',preg_split('/\R+/u',$content)?:[]),fn($line)=>mb_strlen($line)>30)),0,6));$description='Official textbook chapter '.$number.'.';
            if($lesson){$lessonId=(int)$lesson['id'];$u=$db->prepare("UPDATE lessons SET unit_id=?,title_$field=?,short_description_$field=?,content_$field=?,short_notes_$field=?,summary_$field=?,content_source='textbook',status='active' WHERE id=?");$u->bind_param('isssssi',$unitId,$title,$description,$content,$content,$summary,$lessonId);$u->execute();}
            else{$u=$db->prepare("INSERT INTO lessons(grade_id,medium,content_source,subject_id,unit_id,title_$field,short_description_$field,content_$field,short_notes_$field,summary_$field,display_order,status) VALUES(?,?,'textbook',?,?,?,?,?,?,?,?,'active')");$u->bind_param('isiisssssi',$grade,$medium,$subject,$unitId,$title,$description,$content,$content,$summary,$number);$u->execute();$lessonId=(int)$db->insert_id;}
            $parts[]=['lesson'=>['id'=>$lessonId],'text'=>$content];
        }
        $db->commit();$GLOBALS['studio_section_parts']=$parts;
    }catch(Throwable $e){$db->rollback();throw $e;}
}
function studio_pdf(string $path,string $encoding):string{@set_time_limit(900);$medium=(string)($_POST['medium']??'');if($medium!=='Sinhala'&&$encoding==='auto')$encoding='unicode';$cmd=[studio_python(),__DIR__.'/../scripts/extract_curriculum_pdf.py',$path,$encoding];$pipes=[];$p=proc_open($cmd,[['pipe','r'],['pipe','w'],['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);if(!is_resource($p))throw new RuntimeException('PDF reader could not start.');fclose($pipes[0]);$out=(string)stream_get_contents($pipes[1]);$err=(string)stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0)throw new RuntimeException('PDF reading failed: '.trim($err));$data=json_decode($out,true,512,JSON_THROW_ON_ERROR);$text=trim((string)($data['text']??''));$legacy=preg_match_all('/(?:\b(?:laI|fY|m%|ks|j¾)[A-Za-z%¾]*\b|[Èúñ])/u',$text);if($encoding==='auto'&&$medium==='Sinhala'&&$legacy>10)return studio_pdf($path,'fm_abhaya');$text=studio_validate_text($text);studio_seed_sections((array)($data['sections']??[]),(array)($data['page_texts']??[]));return $text;}
function studio_upload(string $name):array{$token=(string)($_POST[$name.'_token']??'');if($token!==''){if(!preg_match('/^[a-f0-9]{32}$/',$token))throw new RuntimeException('Invalid PDF upload token.');$directory=sys_get_temp_dir().'/educhat_pdf_'.hash('sha256',session_id());$path=$directory.'/'.$token.'.pdf';if(!is_file($path))throw new RuntimeException('The uploaded PDF expired. Select it again.');$f=['tmp_name'=>$path,'name'=>$name.'.pdf','size'=>filesize($path),'error'=>UPLOAD_ERR_OK];}else{if(!isset($_FILES[$name])||$_FILES[$name]['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Select every required PDF.');$f=$_FILES[$name];}if($f['size']>30*1024*1024||file_get_contents($f['tmp_name'],false,null,0,5)!=='%PDF-')throw new RuntimeException('Use valid PDFs no larger than 30 MB.');return $f;}
function studio_ai(string $prompt):array{if(GEMINI_API_KEY==='')throw new RuntimeException('GEMINI_API_KEY is required to read papers and answer sheets.');$payload=json_encode(['contents'=>[['parts'=>[['text'=>mb_substr($prompt,0,95000)]]]],'generationConfig'=>['responseMimeType'=>'application/json','temperature'=>0.05]],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$r=gemini_http_json(GEMINI_API_BASE.rawurlencode(GEMINI_MODEL).':generateContent?key='.rawurlencode(GEMINI_API_KEY),['Content-Type: application/json'],$payload);if($r['status']!==200)throw new RuntimeException('AI document reading failed. '.$r['error']);$body=json_decode($r['body'],true,512,JSON_THROW_ON_ERROR);return json_decode((string)($body['candidates'][0]['content']['parts'][0]['text']??''),true,512,JSON_THROW_ON_ERROR);}
function studio_parts(array $lessons,string $text,string $field):array{if(!empty($GLOBALS['studio_section_parts']))return $GLOBALS['studio_section_parts'];$hits=[];foreach($lessons as $l){$title=trim((string)($l['title_'.$field]?:$l['title_en']));$at=mb_strlen($title)>2?mb_stripos($text,$title):false;if($at!==false)$hits[]=['at'=>$at,'lesson'=>$l];}usort($hits,fn($a,$b)=>$a['at']<=>$b['at']);if(!$hits&&$lessons)$hits[]=['at'=>0,'lesson'=>$lessons[0]];$out=[];foreach($hits as $i=>$h){$end=$hits[$i+1]['at']??mb_strlen($text);$out[]=['lesson'=>$h['lesson'],'text'=>trim(mb_substr($text,$h['at'],$end-$h['at']))];}return $out;}
$grades=$db->query("SELECT id,grade_number FROM grades WHERE status='active' ORDER BY grade_number")->fetch_all(MYSQLI_ASSOC);$subjects=$db->query("SELECT id,grade_id,name_en FROM subjects WHERE status='active' ORDER BY grade_id,name_en")->fetch_all(MYSQLI_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['kind']??'notes')==='notes'){
 verify_csrf();
 $preGrade=filter_input(INPUT_POST,'grade_id',FILTER_VALIDATE_INT);$preSubject=filter_input(INPUT_POST,'subject_id',FILTER_VALIDATE_INT);$preMedium=(string)($_POST['medium']??'');if($preMedium!=='Sinhala'&&($_POST['encoding']??'auto')==='auto')$_POST['encoding']='unicode';
 if($preGrade&&$preSubject&&in_array($preMedium,['Sinhala','Tamil','English'],true)&&query_one('SELECT id FROM subjects WHERE id=? AND grade_id=?','ii',[$preSubject,$preGrade])){
  $exists=query_one("SELECT id FROM lessons WHERE grade_id=? AND subject_id=? AND medium=? AND status='active' AND content_source='textbook' LIMIT 1",'iis',[$preGrade,$preSubject,$preMedium]);
  if(!$exists){$fileName=(string)($_FILES['question_pdf']['name']??'Imported textbook');$title=trim((string)pathinfo($fileName,PATHINFO_FILENAME));if($title==='')$title='Imported textbook';$unitNumber=(int)(query_one('SELECT COALESCE(MAX(unit_number),0)+1 n FROM units WHERE subject_id=?','i',[$preSubject])['n']??1);$unit=$db->prepare('INSERT INTO units(grade_id,subject_id,unit_number,name_en,name_si,name_ta,display_order,status) VALUES(?,?,?,?,?,?,?,"active")');$unit->bind_param('iiisssi',$preGrade,$preSubject,$unitNumber,$title,$title,$title,$unitNumber);$unit->execute();$unitId=(int)$db->insert_id;$field=['Sinhala'=>'si','Tamil'=>'ta','English'=>'en'][$preMedium];$order=(int)(query_one('SELECT COALESCE(MAX(display_order),0)+1 n FROM lessons WHERE subject_id=? AND medium=?','is',[$preSubject,$preMedium])['n']??1);$lesson=$db->prepare("INSERT INTO lessons(grade_id,medium,content_source,subject_id,unit_id,title_$field,short_description_$field,display_order,status) VALUES(?,?,'textbook',?,?,?,'Imported textbook ready for curriculum processing.',?,'active')");$lesson->bind_param('isiisi',$preGrade,$preMedium,$preSubject,$unitId,$title,$order);$lesson->execute();}
 }
}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$grade=filter_input(INPUT_POST,'grade_id',FILTER_VALIDATE_INT);$subject=filter_input(INPUT_POST,'subject_id',FILTER_VALIDATE_INT);$medium=(string)($_POST['medium']??'');$kind=(string)($_POST['kind']??'notes');$encoding=(string)($_POST['encoding']??'auto');if(!$grade||!$subject||!in_array($medium,['Sinhala','Tamil','English'],true)||!in_array($kind,['notes','paper'],true))throw new RuntimeException('Choose grade, medium, subject and upload type.');if(!query_one('SELECT id FROM subjects WHERE id=? AND grade_id=?','ii',[$subject,$grade]))throw new RuntimeException('That subject does not belong to the grade.');$question=studio_upload('question_pdf');$questionText=studio_pdf($question['tmp_name'],$encoding);if(mb_strlen($questionText)<100)throw new RuntimeException('No readable text found. Image scans need OCR.');$db->begin_transaction();if($kind==='notes'){$field=['Sinhala'=>'si','Tamil'=>'ta','English'=>'en'][$medium];$q=$db->prepare("SELECT l.* FROM lessons l WHERE l.grade_id=? AND l.subject_id=? AND l.medium=? AND l.status='active' AND l.content_source='textbook' ORDER BY l.display_order,l.id");$q->bind_param('iis',$grade,$subject,$medium);$q->execute();$lessons=$q->get_result()->fetch_all(MYSQLI_ASSOC);if(!$lessons)throw new RuntimeException('No active lessons exist for this selection.');$parts=studio_parts($lessons,$questionText,$field);foreach($parts as $part){if(mb_strlen($part['text'])<80)continue;$lines=array_values(array_filter(array_map('trim',preg_split('/\R+/u',$part['text'])?:[]),fn($x)=>mb_strlen($x)>30));$summary=implode("\n",array_map(fn($x)=>'- '.$x,array_slice($lines,0,6)));$description='Admin-imported notes automatically matched to this lesson.';$id=(int)$part['lesson']['id'];$u=$db->prepare("UPDATE lessons SET short_notes_$field=?,summary_$field=?,short_description_$field=? WHERE id=?");$u->bind_param('sssi',$part['text'],$summary,$description,$id);$u->execute();}$message=count($parts).' lesson section(s) detected and updated.';}else{$answer=studio_upload('answer_pdf');$answerText=studio_pdf($answer['tmp_name'],$encoding);$title=trim((string)($_POST['paper_title']??''));$marks=max(1,(int)($_POST['total_marks']??100));$minutes=max(0,(int)($_POST['duration_minutes']??0));if($title==='')throw new RuntimeException('Enter a paper title.');$prompt='Match the QUESTION PAPER and ANSWER SHEET below. Return JSON only: array of objects with number, question, answer, marks. Preserve subquestions and allocate marks so the total is exactly '.$marks.'. QUESTION PAPER: '.$questionText.' ANSWER SHEET: '.$answerText;$items=studio_ai($prompt);if(!$items)throw new RuntimeException('No marked questions found.');$p=$db->prepare("INSERT INTO practice_papers(grade_id,subject_id,medium,title,total_marks,duration_minutes) VALUES(?,?,?,?,?,?)");$p->bind_param('iissii',$grade,$subject,$medium,$title,$marks,$minutes);$p->execute();$paperId=(int)$db->insert_id;foreach($items as $i=>$item){$number=(string)($item['number']??$i+1);$qt=trim((string)($item['question']??''));$at=trim((string)($item['answer']??''));$mk=(float)($item['marks']??0);if($qt===''||$at==='')continue;$order=$i+1;$x=$db->prepare('INSERT INTO paper_questions(paper_id,question_number,question_text,answer_text,marks,display_order) VALUES(?,?,?,?,?,?)');$x->bind_param('isssdi',$paperId,$number,$qt,$at,$mk,$order);$x->execute();}$message='Paper, answers and marking allocation imported.';}$db->commit();flash('success',$message);}catch(Throwable $e){if(isset($db)&&$db instanceof mysqli)@$db->rollback();flash('error',$e->getMessage());}redirect('admin/curriculum_manager.php');}
$papers=$db->query("SELECT p.*,g.grade_number,s.name_en,(SELECT COUNT(*) FROM paper_questions q WHERE q.paper_id=p.id) questions,(SELECT COALESCE(SUM(marks),0) FROM paper_questions q WHERE q.paper_id=p.id) allocated FROM practice_papers p JOIN grades g ON g.id=p.grade_id JOIN subjects s ON s.id=p.subject_id ORDER BY p.id DESC LIMIT 20")->fetch_all(MYSQLI_ASSOC);$pageTitle='Curriculum Studio';include __DIR__.'/_top.php';?>
<style>.studio-hero{background:linear-gradient(135deg,#101936,#344ca1 60%,#058ba7);color:#fff}.studio-hero p{color:#d3ddff}.studio-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.studio-grid .wide{grid-column:1/-1}.paper-fields{display:none}.paper-fields.show{display:contents}@media(max-width:700px){.studio-grid{grid-template-columns:1fr}.studio-grid .wide{grid-column:auto}}</style><section class="card studio-hero"><span class="badge">Smart administration</span><h1>Curriculum Studio</h1><p>Select Grade, Medium and Subject. Notes are matched to lessons automatically. Papers use their answer sheet to create answers and marks.</p></section><section class="card"><form method="post" enctype="multipart/form-data" class="studio-grid"><?=csrf_field()?><label>Grade<select name="grade_id" id="grade" required><option value="">Choose grade</option><?php foreach($grades as $g):?><option value="<?=$g['id']?>">Grade <?=$g['grade_number']?></option><?php endforeach;?></select></label><label>Medium<select name="medium" required><option>Sinhala</option><option>Tamil</option><option>English</option></select></label><label>Subject<select name="subject_id" id="subject" required><option value="">Choose subject</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" data-grade="<?=$s['grade_id']?>"><?=e($s['name_en'])?></option><?php endforeach;?></select></label><label>Upload type<select name="kind" id="kind"><option value="notes">Subject notes / textbook</option><option value="paper">Past paper + answer sheet</option></select></label><label>Encoding<select name="encoding"><option value="auto">Auto detect</option><option value="unicode">Unicode</option><option value="fm_abhaya">Legacy FM Abhaya Sinhala</option></select></label><label>Subject PDF / Question paper<input type="file" name="question_pdf" accept=".pdf,application/pdf" required></label><div class="paper-fields" id="paperFields"><label>Paper title<input name="paper_title"></label><label>Total marks<input type="number" name="total_marks" value="100" min="1"></label><label>Duration (minutes)<input type="number" name="duration_minutes" value="120" min="0"></label><label>Answer sheet PDF<input type="file" name="answer_pdf" accept=".pdf,application/pdf"></label></div><button class="wide">Read, match and import</button></form></section><?php if($papers):?><section class="card"><h2>Imported papers</h2><div class="scroll"><table><tr><th>Paper</th><th>Target</th><th>Questions</th><th>Marks</th></tr><?php foreach($papers as $p):?><tr><td><?=e($p['title'])?></td><td>Grade <?=$p['grade_number']?> · <?=e($p['medium'])?> · <?=e($p['name_en'])?></td><td><?=$p['questions']?></td><td><?=e($p['allocated'])?> / <?=$p['total_marks']?></td></tr><?php endforeach;?></table></div></section><?php endif;?><script>const g=document.querySelector('#grade'),s=document.querySelector('#subject'),k=document.querySelector('#kind'),pf=document.querySelector('#paperFields');g.onchange=()=>{[...s.options].forEach(o=>o.hidden=o.value&&o.dataset.grade!==g.value);if(s.selectedOptions[0]?.hidden)s.value=''};k.onchange=()=>{const on=k.value==='paper';pf.classList.toggle('show',on);pf.querySelectorAll('input').forEach(i=>{if(['answer_pdf','paper_title'].includes(i.name))i.required=on})};k.onchange();</script><?php include __DIR__.'/../includes/footer.php';
